from fractions import Fraction
from math import gcd
def k_analytic(p,q):
    return 2*q // gcd(q+2*p,2*q)
def check(k,p,q,limit=400):
    a=Fraction(p,q)
    return all((Fraction(k,2)*(n*n+2*a*n)).denominator==1 for n in range(-limit,limit+1))
bad=[]
for q in range(1,31):
    for p in range(-2*q,2*q+1):
        if gcd(p,q)!=1: continue
        ka=k_analytic(p,q)
        if not check(ka,p,q,60) or any(check(j,p,q,15) for j in range(1,ka)):
            bad.append((p,q,ka))
len(bad)

