}

BRANCHES = {
    "directive_intake": {"tags": {"directive", "current", "notice"}, "relation": "serial", "share": True},
    "capability_scout": {"tags": {"blocked", "capability", "tool", "plugin"}, "relation": "parallel", "share": True},
